import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            tstat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            pval = 2 * (1 - stats.t.cdf(abs(tstat), feats.n - 1))
            if pval < 0.05:
                sig_features.append((fid, i, pval))

    # Sort by significance
    sig_features.sort(key=lambda x: x[2])

    # Check for correlated pairs
    correlations = {}
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(feats.ids[i], feats.ids[j])] = corr

    # Look for product terms among significant features
    best_product = None
    best_p = 1.0
    best_pair = None

    for fid1, i1, _ in sig_features[:10]:
        for fid2, i2, _ in sig_features[:10]:
            if i1 >= i2:
                continue
            # Check if pair is correlated
            if (fid1, fid2) in correlations or (fid2, fid1) in correlations:
                # Create product feature
                product = feats.x[:, i1] * feats.x[:, i2]
                # Fit logistic regression
                lr = LogisticRegression(fit_intercept=True, max_iter=1000)
                lr.fit(product.reshape(-1, 1), feats.y)
                # Calculate p-value using chi-squared test
                y_pred = lr.predict_proba(product.reshape(-1, 1))[:, 1]
                deviance = -2 * (np.sum(feats.y * np.log(y_pred + 1e-15)) + 
                                np.sum((1 - feats.y) * np.log(1 - y_pred + 1e-15)))
                df = 1
                pval = 1 - stats.chi2.cdf(deviance, df)
                if pval < best_p:
                    best_p = pval
                    best_pair = (fid1, fid2)
                    best_product = product

    # If we found a significant product term
    if best_p < 0.05 and best_pair:
        return Design(
            drivers=(best_pair[0], best_pair[1]),
            columns=(best_pair[0], best_pair[1]),
            products=(best_pair,),
            loadings={best_pair[0]: 1.0, best_pair[1]: 1.0}
        )

    # Otherwise, use top significant features
    if sig_features:
        drivers = [f[0] for f in sig_features[:min(MAX_DRIVERS, len(sig_features))]]
        return Design(
            drivers=tuple(drivers),
            columns=tuple([f[0] for f in sig_features[:10]]),
            products=(),
            loadings={f[0]: 1.0 for f in sig_features[:10]}
        )

    # No mechanism case
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

